using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any public type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded  →  {found!.Type.Name}");
}

// Now demonstrate a resolver that does NOT know about a type.
// Source-gen context that only handles Person:
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int> succeeded  →  {intInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> returned false — metadata not available (no exception thrown)");
}

// Record used in the demo
public record Person(string Name, int Age);

// A source-gen context that only exposes Person
[JsonSerializable(typeof(Person))]
internal partial class LimitedContext : JsonSerializerContext;

